"""Signature checks for the event requests Corvid Payments sends us."""

import base64
import hashlib
import hmac
import re


def _key(secret: str):
    if not isinstance(secret, str) or not secret.startswith("whsec_"):
        return None
    try:
        return base64.b64decode(secret[len("whsec_"):], validate=True)
    except Exception:
        return None


def verify(headers: dict[str, str], body: bytes, secrets: list[str], now: int) -> bool:
    """True when the request carries a valid Corvid signature, else False. Never raises.

    `headers` are the request headers, `body` the request body as received, `secrets` the
    signing secrets the receiver holds (`whsec_...`), `now` the current time in Unix seconds.
    """
    try:
        lower = {str(k).lower(): v for k, v in headers.items()}
        sig = lower.get("corvid-signature")
        event_id = lower.get("corvid-event-id")
        if not isinstance(sig, str) or not isinstance(event_id, str) or not event_id:
            return False
        ts = []
        v2 = []
        for part in sig.split(","):
            part = part.lstrip(" ")
            name, sep, value = part.partition("=")
            if not sep or not name:
                return False
            if name == "t":
                ts.append(value)
            elif name == "v2":
                v2.append(value)
        if len(ts) != 1 or not re.fullmatch(r"[0-9]+", ts[0]):
            return False
        t = int(ts[0])
        if t < now - 300 or t > now + 60:
            return False
        v2 = [v for v in v2 if re.fullmatch(r"[0-9a-f]{64}", v)]
        if not v2:
            return False
        payload = b"v2:" + ts[0].encode() + b":" + event_id.encode() + b":" + bytes(body)
        ok = False
        for secret in secrets:
            key = _key(secret)
            if key is None:
                continue
            expected = hmac.new(key, payload, hashlib.sha256).hexdigest()
            for v in v2:
                if hmac.compare_digest(v, expected):
                    ok = True
        return ok
    except Exception:
        return False
EOF
