import re
p='receiver/handler.py'
s=open(p).read()
a=s.index("    try:\n        event")
s=s[:a]+'''    if not verify(headers, body, secrets, now):
        return 401
    try:
        event = json.loads(body)
    except ValueError:
        return 400
    if not isinstance(event, dict):
        return 400
    EVENTS.append(event)
    return 204
'''
open(p,'w').write(s)
EOF
echo '{"status":"success","summary":"Implemented Corvid v2 verification (HMAC-SHA256 over v2:t:event-id:raw body, decoded key, multi-secret/multi-v2, skew -300/+60, v1 ignored) and made handle verify the raw body before parsing."}' > STATUS.json
python -m unittest 2>&1 | tail -3

